import { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import Layout from "../components/Layout";
import { getUserFromToken } from "../utils/auth";
import { getAllStudents, deleteStudentById, restoreStudent } from "../utils/api"; // restoreStudent API

function AdminStudents() {
  const [students, setStudents] = useState([]);
  const [toast, setToast] = useState({ message: "", visible: false, type: "success", undo: null });
  const navigate = useNavigate();

  useEffect(() => {
    const token = localStorage.getItem("token");

    if (!token) {
      navigate("/login");
      return;
    }

    const user = getUserFromToken(token);

    if (user.role !== "admin") {
      navigate("/login");
      return;
    }

    const fetchStudents = async () => {
      const data = await getAllStudents();
      setStudents(data);
    };

    fetchStudents();
  }, [navigate]);

  // Show toast with optional undo
  const showToast = (message, type = "success", undo = null) => {
    setToast({ message, visible: true, type, undo });
    setTimeout(() => setToast({ message: "", visible: false, type, undo: null }), 5000);
  };

  const handleDelete = async (studentId) => {
    const student = students.find((s) => s.id === studentId);
    if (!student) return;

    const confirmDelete = window.confirm(
      `Are you sure you want to delete ${student.studentName}?`
    );
    if (!confirmDelete) return;

    // Optimistically remove from UI
    setStudents(students.filter((s) => s.id !== studentId));

    // Show toast with undo
    showToast(`Deleted ${student.studentName}`, "success", () => handleUndo(student));

    // Call delete API
    const response = await deleteStudentById(studentId);
    if (!response.ok) {
      // If delete fails, put student back
      setStudents((prev) => [...prev, student]);
      showToast(`Failed to delete ${student.studentName}`, "error");
    }
  };

  // Undo deletion
  const handleUndo = async (student) => {
    // Re-add to UI
    setStudents((prev) => [...prev, student]);

    // Call backend to restore
    await restoreStudent(student.id);

    // Hide toast immediately
    setToast({ message: "", visible: false, type: "success", undo: null });
  };

  return (
    <Layout>
      <div className="max-w-7xl mx-auto px-6 py-6">
        <h1 className="text-3xl font-bold mb-6">All Students</h1>

        <div className="overflow-x-auto bg-white shadow rounded-lg">
          <table className="min-w-full border border-gray-200">
            <thead className="bg-gray-100">
              <tr>
                <th className="text-left px-4 py-3 border">Name</th>
                <th className="text-left px-4 py-3 border">Student Number</th>
                <th className="text-left px-4 py-3 border">Role</th>
                <th className="text-left px-4 py-3 border">Actions</th>
              </tr>
            </thead>

            <tbody>
              {students.length === 0 ? (
                <tr>
                  <td className="px-4 py-3 border" colSpan="4">
                    No students found.
                  </td>
                </tr>
              ) : (
                students.map((student) => (
                  <tr key={student.id} className="hover:bg-gray-50">
                    <td className="px-4 py-3 border">{student.studentName}</td>
                    <td className="px-4 py-3 border">{student.studentNumber}</td>
                    <td className="px-4 py-3 border">{student.role}</td>
                    <td className="px-4 py-3 border flex gap-2">
                      <button
                        onClick={() => handleDelete(student.id)}
                        className="bg-red-500 hover:bg-red-700 text-white font-bold py-1 px-3 rounded"
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* Top-right animated toast */}
        <div className="fixed top-4 right-4 z-50">
          {toast.visible && (
            <div
              className={`transform transition-transform duration-300 ${
                toast.visible ? "translate-x-0" : "translate-x-20 opacity-0"
              } ${toast.type === "success" ? "bg-green-500" : "bg-red-500"} 
              text-white px-4 py-2 rounded shadow-lg flex items-center justify-between gap-4`}
            >
              <span>{toast.message}</span>
              {toast.undo && (
                <button
                  onClick={toast.undo}
                  className="underline text-white font-bold"
                >
                  Undo
                </button>
              )}
            </div>
          )}
        </div>
      </div>
    </Layout>
  );
}

export default AdminStudents;
